evidence.snippet:
    - mapping: |
        root = this.usgs.or([]).concat(this.nws.or([]))

    - unarchive:
        format: json_array

    - dedupe:
        cache: seen_hazards
        key: '${!this.id}'

    - mapping: |
        let ts = now().format_timestamp("2006-01-02T15:04:05.000Z")
        let stale = (now().ts_unix() + this.stale_s.number()).ts_format("2006-01-02T15:04:05.000Z")
        let callsign = if this.source == "USGS" {
          "M" + this.mag.format_number(1) + " Earthquake"
        } else {
          this.event
        }
        let remarks = if this.source == "USGS" {
          "M" + this.mag.format_number(1) + " " + this.place + " depth:" + this.depth.format_number(1) + "km"
        } else {
          this.severity + ": " + this.headline
        }
        root = "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\" ?>\n<event version=\"2.0\" type=\"b-r-f-h-h\" uid=\"" + this.uid + "\" how=\"h-e\" time=\"" + $ts + "\" start=\"" + $ts + "\" stale=\"" + $stale + "\"><point lat=\"" + this.lat.string() + "\" lon=\"" + this.lon.string() + "\" hae=\"" + this.hae + "\" ce=\"9999999.0\" le=\"9999999.0\"/><detail><contact callsign=\"" + $callsign + "\"/><status readiness=\"false\"/><remarks>" + $remarks + "</remarks><marti><dest mission=\"Hazards\"/></marti></detail></event>"

output:
  nats:
    urls: ["nats://nats.nats.svc.cluster.local:4222"]
    subject: "tak.cot.inject"
    auth:
      user: "${NATS_USER}"
      password: "[REDACTED]"
    tls:
      enabled: true
      skip_cert_verify: true

feed-ships.yaml: |
  input:
    websocket:
      url: "wss://stream.aisstream.io/v0/stream"
      open_message: '{"APIKey": "${AISSTREAM_API_KEY}", "BoundingBoxes": [[[-90, -180], [90, 180]]]}'
      open_message_type: text
      tls:
        enabled: true

  pipeline:
    processors:
      - mapping: |
          let md = this.MetaData.or({})
          let mmsi = $md.MMSI.or($md.UserID)
          let lat = $md.latitude.or($md.Latitude)
          let lon = $md.longitude.or($md.Longitude)
          root = if $mmsi == null || $lat == null || $lon == null { deleted() } else {
            let pr = this.Message.or({})
            let pos = $pr.PositionReport.or($pr.StandardClassBPositionReport.or({}))
            let sog = $pos.Sog.or(0)
            let cog = $pos.Cog.or(0)
            let sdata = $pr.ShipStaticData.or({})
            let ship_name = $sdata.Name.or($md.ShipName.or("")).string().trim()
            let cs = if $ship_name == "" { $mmsi.string() } else { $ship_name.slice(0, 32).replace_all("&", "&amp;").replace_all("<", "&lt;").replace_all("\"", "&quot;") }
            let stype = $sdata.Type.Code.or("").string()
            {
              "uid": "AIS-" + $mmsi.string(),
              "callsign": $cs,
              "lat": $lat,
              "lon": $lon,
              "sog": $sog,
              "cog": $cog,
              "mmsi": $mmsi,
              "stype": $stype
            }
          }

      - mapping: |
          let ts = now().format_timestamp("2006-01-02T15:04:05.000Z")
          let stale = (now().ts_unix() + 300).ts_format("2006-01-02T15:04:05.000Z")
          root = "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\" ?>\n<event version=\"2.0\" type=\"a-f-S-X-M\" uid=\"" + this.uid + "\" how=\"m-g\" time=\"" + $ts + "\" start=\"" + $ts + "\" stale=\"" + $stale + "\"><point lat=\"" + this.lat.string() + "\" lon=\"" + this.lon.string() + "\" hae=\"-10000\" ce=\"9999999.0\" le=\"9999999.0\"/><detail><contact callsign=\"" + this.callsign + "\"/><track speed=\"" + this.sog.string() + "\" course=\"" + this.cog.string() + "\"/><status readiness=\"false\"/><remarks>MMSI:" + this.mmsi.string() + " " + this.stype + "</remarks><marti><dest mission=\"Sea\"/></marti></detail></event>"

  output:
    nats:
      urls: ["nats://nats.nats.svc.cluster.local:4222"]
      subject: "tak.cot.inject"
      auth:
        user: "${NATS_USER}"
        password: "[REDACTED]"
      tls:
        enabled: true
        skip_cert_verify: true

async def poll(session: aiohttp.ClientSession, js, seen: set, areas: list[str]) -> int:
    params: dict[str, str] = {"status": "actual"}
    if areas and areas != ["US"]:
        params["area"] = ",".join(areas)
    url = f"{NOAA_BASE}/alerts/active"
    try:
        async with session.get(
            url,
            params=params,
            headers={"Accept": "application/geo+json", "User-Agent": "omos-feed-intel-noaa/1.0"},
            timeout=aiohttp.ClientTimeout(total=30),
        ) as r:
            if r.status != 200:
                LOG.warning(f"NOAA HTTP {r.status}")
                return 0
            data = await r.json(content_type=None)
    except Exception as e:
        LOG.error(f"NOAA fetch error: {e}")
        return 0

    features  = data.get("features", [])
    published = 0
    for feat in features:
        alert_id = feat.get("id", "")
        if not alert_id or alert_id in seen:
            continue

