def flush_to_clickhouse(batch: list[dict]) -> None:
    body = "\n".join(json.dumps(row) for row in batch).encode("utf-8")
    req = urllib.request.Request(
        CH_URL,
        data=body,
        method="POST",
        headers={
            "Content-Type": "application/x-ndjson",
            "X-ClickHouse-User": CH_USER,
            "X-ClickHouse-Key":  CH_PASSWORD,
        },
    )
    try:
        with urllib.request.urlopen(req, timeout=10) as resp:
            status = resp.status
        LOG.info("flushed batch=%d status=%d", len(batch), status)
    except urllib.error.HTTPError as exc:
        body_text = exc.read(512).decode("utf-8", errors="replace")
        LOG.error("ClickHouse HTTP %d — batch discarded: %s", exc.code, body_text)
    except Exception as exc:
        LOG.error("ClickHouse unavailable — batch discarded: %s", exc)

private void onNatsMessage(io.nats.client.Message natsMsg) {
    try {
        String cotXml = new String(natsMsg.getData(), StandardCharsets.UTF_8);
        logger.debug("NATS→TAK [{}]: {}", consumerSubject, cotXml.substring(0, Math.min(120, cotXml.length())));

        Message takMessage = getConverter().cotStringToDataMessage(
            cotXml,
            groups,
            Integer.toString(System.identityHashCode(this))
        );
        send(takMessage);
    } catch (Exception e) {
        logger.error("Error injecting NATS message into TAK", e);
    }

@Override
public void start() {
    logger.info("NatsBridgePlugin starting — connecting to {}", natsUrl);
    try {
        Options options = new Options.Builder()
            .server(natsUrl)
            .maxReconnects(-1)          // reconnect forever
            .reconnectWait(java.time.Duration.ofSeconds(2))
            .connectionName("takserver-nats-bridge")
            .build();

        natsConnection = Nats.connect(options);
        logger.info("NatsBridgePlugin connected to NATS");

        // Subscribe to inbound CoT subject
        natsDispatcher = natsConnection.createDispatcher(this::onNatsMessage);
        natsDispatcher.subscribe(consumerSubject);
        logger.info("NatsBridgePlugin subscribed to NATS subject: {}", consumerSubject);

    } catch (Exception e) {
        logger.error("NatsBridgePlugin failed to connect to NATS at {}", natsUrl, e);
    }

def build_ssl_context() -> ssl.SSLContext:
    ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_CLIENT)
    if VERIFY_SERVER and os.path.exists(TAK_CA):
        ctx.load_verify_locations(cafile=TAK_CA)
        ctx.check_hostname = False
        ctx.verify_mode = ssl.CERT_REQUIRED
    else:
        ctx.check_hostname = False
        ctx.verify_mode = ssl.CERT_NONE
    ctx.load_cert_chain(certfile=TAK_CERT, keyfile=TAK_KEY)

async def stream_tak(nc):
    ssl_ctx = build_ssl_context()
    reader, writer = await asyncio.open_connection(TAK_HOST, TAK_PORT, ssl=ssl_ctx)
    LOG.info("TLS connected to TAK %s:%s", TAK_HOST, TAK_PORT)
    buf = b""
    count = 0
    try:
        while True:
            chunk = await reader.read(8192)
            if not chunk:
                LOG.warning("TAK stream closed by server")
                break
            buf += chunk
            # frame on </event>
            while True:
                idx = buf.find(EVENT_END)
                if idx == -1:
                    break
                end = idx + len(EVENT_END)
                raw = buf[:end]
                buf = buf[end:]
                start = raw.find(b"<event")
                if start == -1:
                    continue
                event = raw[start:]
                try:
                    await nc.publish(NATS_SUBJECT, event)
                    count += 1
                    if count <= 5 or count % 50 == 0:
                        LOG.info("published CoT #%d (%d bytes) to %s", count, len(event), NATS_SUBJECT)
                except Exception as e:
                    LOG.error("NATS publish failed: %s", e)

// ── NATS command subscriber (omos.field.*.command → TAK server) ──────────
cmdSubject := "omos.field.*.command"
takServerAddr := fmt.Sprintf("%s:%d", cfg.serverHost, cfg.serverPort)
raddr, err := net.ResolveUDPAddr("udp4", takServerAddr)
if err != nil {
	log.Fatalf("[%s] resolve TAK server addr %s: %v", cfg.bridgeName, takServerAddr, err)
}

sub, err := nc.Subscribe(cmdSubject, func(msg *nats.Msg) {
	cotXML := buildCommandCoT(msg.Data)

	udpConn, err := net.DialUDP("udp4", nil, raddr)
	if err != nil {
		log.Printf("[%s] dial TAK server %s: %v", cfg.bridgeName, takServerAddr, err)
		publishError(fmt.Sprintf("dial tak server: %v", err))
		return
	}
	defer udpConn.Close()

	if _, err := udpConn.Write(cotXML); err != nil {
		log.Printf("[%s] send command to TAK server: %v", cfg.bridgeName, err)
		publishError(fmt.Sprintf("send cmd to tak: %v", err))
		return
	}
	log.Printf("[%s] forwarded command from subject %s → TAK %s", cfg.bridgeName, msg.Subject, takServerAddr)
})
